/**
 * @file Column helpers shared by the app's tables (not Better Auth's, which
 * are generated).
 */
import { sql } from 'drizzle-orm';
import { timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * Primary key column: a UUIDv7 generated by Postgres. Time-ordered, so new
 * rows append to the index.
 *
 * @returns The column definition.
 */
export const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

/**
 * Timestamp column with time zone.
 *
 * @param name - The column name.
 * @returns The column definition.
 */
export const timestampTz = (name: string) => timestamp(name, { withTimezone: true });

/**
 * Creation time column, set by the database.
 *
 * @returns The column definition.
 */
export const createdAt = () => timestampTz('created_at').defaultNow().notNull();
